(window.__quranSurahs=window.__quranSurahs||{})[78]={"nomPhon":"An-Naba","versets":{"1":{"text":"Sur quoi s'interrogent-ils mutuellement?","arabe":"عَمَّ يَتَسَآءَلُونَ"},"2":{"text":"Sur la grande nouvelle,","arabe":"عَنِ ٱلنَّبَإِ ٱلْعَظِيمِ"},"3":{"text":"à propos de laquelle ils divergent.","arabe":"ٱلَّذِى هُمْ فِيهِ مُخْتَلِفُونَ"},"4":{"text":"Eh bien non! Ils sauront bientôt.","arabe":"كَلَّا سَيَعْلَمُونَ"},"5":{"text":"Encore une fois, non! Ils sauront bientôt.","arabe":"ثُمَّ كَلَّا سَيَعْلَمُونَ"},"6":{"text":"N'avons-Nous pas fait de la terre une couche?","arabe":"أَلَمْ نَجْعَلِ ٱلْأَرْضَ مِهَٰدًۭا"},"7":{"text":"et (placé) les montagnes comme des piquets?","arabe":"وَٱلْجِبَالَ أَوْتَادًۭا"},"8":{"text":"Nous vous avons créés en couples,","arabe":"وَخَلَقْنَٰكُمْ أَزْوَٰجًۭا"},"9":{"text":"et désigné votre sommeil pour votre repos,","arabe":"وَجَعَلْنَا نَوْمَكُمْ سُبَاتًۭا"},"10":{"text":"et fait de la nuit un vêtement,","arabe":"وَجَعَلْنَا ٱلَّيْلَ لِبَاسًۭا"},"11":{"text":"et assigné le jour pour les affaires de la vie,","arabe":"وَجَعَلْنَا ٱلنَّهَارَ مَعَاشًۭا"},"12":{"text":"et construit au-dessus de vous sept (cieux) renforcés,","arabe":"وَبَنَيْنَا فَوْقَكُمْ سَبْعًۭا شِدَادًۭا"},"13":{"text":"et [y] avons placé une lampe (le soleil) très ardente,","arabe":"وَجَعَلْنَا سِرَاجًۭا وَهَّاجًۭا"},"14":{"text":"et fait descendre des nuées une eau abondante","arabe":"وَأَنزَلْنَا مِنَ ٱلْمُعْصِرَٰتِ مَآءًۭ ثَجَّاجًۭا"},"15":{"text":"pour faire pousser par elle grains et plantes","arabe":"لِّنُخْرِجَ بِهِۦ حَبًّۭا وَنَبَاتًۭا"},"16":{"text":"et jardins luxuriants.","arabe":"وَجَنَّٰتٍ أَلْفَافًا"},"17":{"text":"Le Jour de la Décision [du Jugement] a son terme fixé.","arabe":"إِنَّ يَوْمَ ٱلْفَصْلِ كَانَ مِيقَٰتًۭا"},"18":{"text":"Le jour où l'on soufflera dans la Trompe, vous viendrez par troupes,","arabe":"يَوْمَ يُنفَخُ فِى ٱلصُّورِ فَتَأْتُونَ أَفْوَاجًۭا"},"19":{"text":"et le ciel sera ouvert et [présentera] des portes,","arabe":"وَفُتِحَتِ ٱلسَّمَآءُ فَكَانَتْ أَبْوَٰبًۭا"},"20":{"text":"et les montagnes seront mises en marche et deviendront un mirage.","arabe":"وَسُيِّرَتِ ٱلْجِبَالُ فَكَانَتْ سَرَابًا"},"21":{"text":"L'Enfer demeure aux aguets,","arabe":"إِنَّ جَهَنَّمَ كَانَتْ مِرْصَادًۭا"},"22":{"text":"refuge pour les transgresseurs.","arabe":"لِّلطَّٰغِينَ مَـَٔابًۭا"},"23":{"text":"Ils y demeureront pendant des siècles successifs.","arabe":"لَّٰبِثِينَ فِيهَآ أَحْقَابًۭا"},"24":{"text":"Ils n'y goûteront ni fraîcheur ni breuvage,","arabe":"لَّا يَذُوقُونَ فِيهَا بَرْدًۭا وَلَا شَرَابًا"},"25":{"text":"Hormis une eau bouillante et un pus","arabe":"إِلَّا حَمِيمًۭا وَغَسَّاقًۭا"},"26":{"text":"comme rétribution équitable.","arabe":"جَزَآءًۭ وِفَاقًا"},"27":{"text":"Car ils ne s'attendaient pas à rendre compte,","arabe":"إِنَّهُمْ كَانُوا۟ لَا يَرْجُونَ حِسَابًۭا"},"28":{"text":"et traitaient de mensonges, continuellement, Nos versets,","arabe":"وَكَذَّبُوا۟ بِـَٔايَٰتِنَا كِذَّابًۭا"},"29":{"text":"alors que Nous avons dénombré toutes choses en écrit.","arabe":"وَكُلَّ شَىْءٍ أَحْصَيْنَٰهُ كِتَٰبًۭا"},"30":{"text":"Goûtez-donc. Nous n'augmenterons pour vous que le châtiment!","arabe":"فَذُوقُوا۟ فَلَن نَّزِيدَكُمْ إِلَّا عَذَابًا"},"31":{"text":"Pour les pieux ce sera une réussite:","arabe":"إِنَّ لِلْمُتَّقِينَ مَفَازًا"},"32":{"text":"jardins et vignes,","arabe":"حَدَآئِقَ وَأَعْنَٰبًۭا"},"33":{"text":"et des (belles) aux seins arrondis, d'une égale jeunesse,","arabe":"وَكَوَاعِبَ أَتْرَابًۭا"},"34":{"text":"et coupes débordantes.","arabe":"وَكَأْسًۭا دِهَاقًۭا"},"35":{"text":"Ils n'y entendront ni futilités ni mensonges.","arabe":"لَّا يَسْمَعُونَ فِيهَا لَغْوًۭا وَلَا كِذَّٰبًۭا"},"36":{"text":"A titre de récompense de ton Seigneur et à titre de don abondant","arabe":"جَزَآءًۭ مِّن رَّبِّكَ عَطَآءً حِسَابًۭا"},"37":{"text":"du Seigneur des cieux et de la terre et de ce qui existe entre eux, le Tout Miséricordieux; ils n'osent nullement Lui adresser la parole.","arabe":"رَّبِّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ٱلرَّحْمَٰنِ ۖ لَا يَمْلِكُونَ مِنْهُ خِطَابًۭا"},"38":{"text":"Le jour où l'Esprit et les Anges se dresseront en rangs, nul ne saura parler, sauf celui à qui le Tout Miséricordieux aura accordé la permission, et qui dira la vérité.","arabe":"يَوْمَ يَقُومُ ٱلرُّوحُ وَٱلْمَلَٰٓئِكَةُ صَفًّۭا ۖ لَّا يَتَكَلَّمُونَ إِلَّا مَنْ أَذِنَ لَهُ ٱلرَّحْمَٰنُ وَقَالَ صَوَابًۭا"},"39":{"text":"Ce jour-là est inéluctable. Que celui qui veut prenne donc refuge auprès de son Seigneur.","arabe":"ذَٰلِكَ ٱلْيَوْمُ ٱلْحَقُّ ۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ مَـَٔابًا"},"40":{"text":"Nous vous avons avertis d'un châtiment bien proche, le jour où l'homme verra ce que ses deux mains ont préparé; et l'infidèle dira: «Hélas pour moi! Comme j'aurais aimé n'être que poussière».","arabe":"إِنَّآ أَنذَرْنَٰكُمْ عَذَابًۭا قَرِيبًۭا يَوْمَ يَنظُرُ ٱلْمَرْءُ مَا قَدَّمَتْ يَدَاهُ وَيَقُولُ ٱلْكَافِرُ يَٰلَيْتَنِى كُنتُ تُرَٰبًۢا"}}};